#!/usr/bin/env python3
"""Apply the final reviewed delta after the base specialist-audit transformation."""
from __future__ import annotations
import base64, hashlib, subprocess, zlib
PATCH_SHA256 = 'acaa78d711cd4fc17e5d9d7b6661de8f16f3ef5f3f48a8c55eb8044ae3759048'
PATCH = ''
raw = zlib.decompress(base64.b64decode(PATCH, validate=True))
if hashlib.sha256(raw).hexdigest() != PATCH_SHA256:
    raise SystemExit("supplemental patch checksum mismatch")
subprocess.run(["git", "apply", "--whitespace=nowarn", "-"], input=raw, check=True)
print("Applied final specialist-audit delta.")
